window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b2e2f38f4e92b10c"]={"versions": [{"id": "FIG-b2e2f38f4e92b10c", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (Prozessflussdiagramm der AUTOSAR Methodology). Das Diagramm stellt den Übergang von der Systemkonfiguration zur ECU-spezifischen Konfigurationsebene innerhalb der AUTOSAR Classic Platform dar. Es fokussiert auf die Aktivitätskette unmittelbar nach Erstellung und Aktualisierung der Systemkonfigurationsbeschreibung und bildet die Brücke zur Teilmethodik „ECU Design and Configuration Methodology“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst Aktivitäten (gelbe Blockpfeile), Artefakte/Work Products (blaue XML-Dokumentensymbole bzw. weiße Dokumentenreferenz) sowie Toolunterstützung (gelbe Zeichendreieck-/Lineal-Symbole):</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsartefakte</strong>:</li>\n<li><code>System Configuration Input :System</code> (.XML)</li>\n<li><code>Collection of Available SWC Implementations</code> (.XML)</li>\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Configure System</code>: Nimmt die Eingangsbeschreibungen entgegen und erzeugt bzw. aktualisiert die Systemkonfiguration.</li>\n<li><code>Extract ECU-Specific Information</code>: Extrahiert die für ein einzelnes Steuergerät relevanten Daten aus der Systemkonfiguration.</li>\n<li><strong>Zwischen- und Ausgangsartefakte</strong>:</li>\n<li><code>System Configuration Description : System</code> (.XML): Zentrale Systemkonfigurationsbeschreibung, die aus <code>Configure System</code> resultiert und als Eingabe für <code>Extract ECU-Specific Information</code> sowie für die zyklische Rückführung dient.</li>\n<li>Weiteres <code>System Configuration Description</code>-Fragment / rückgeführtes Systemmodell (.XML) am unteren Rand.</li>\n<li><code>Continued in \"ECU Design and Configuration Methodology\"</code>: Weiterführungshinweis auf das ECU-spezifische Folge-Artefakt (ECU Extract of System Configuration).</li>\n<li><strong>Werkzeuge</strong>:</li>\n<li>AUTOSAR-Systemkonfigurationswerkzeug (assoziiert mit <code>Configure System</code>).</li>\n<li>AUTOSAR-ECU-Extraktionswerkzeug (assoziiert mit <code>Extract ECU-Specific Information</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Eingangsartefakte <code>System Configuration Input :System</code> und <code>Collection of Available SWC Implementations</code> fließen über gerichtete Kanten in den Prozessschritt <code>Configure System</code> ein.</li>\n<li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.</li>\n<li>Aus der <code>System Configuration Description : System</code> führt ein gerichteter Kontroll-/Datenfluss direkt in die nachgelagerte Aktivität <code>Extract ECU-Specific Information</code>.</li>\n<li>Parallel dazu existiert eine Rückkopplungs- bzw. Verfeinerungsschleife: Ein Pfeil führt von <code>Configure System</code> sowie eine gestrichelte Assoziation von <code>System Configuration Description : System</code> auf das darunterliegende XML-Artefakt der Systemkonfiguration.</li>\n<li><code>Extract ECU-Specific Information</code> verarbeitet die Systemkonfiguration und leitet das Ergebnis in den nachfolgenden Methodenbereich über, visualisiert durch das Referenzdokument <code>Continued in \"ECU Design and Configuration Methodology\"</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Prozessabfolge der AUTOSAR-Methodik. Entwickler und Tool-Hersteller müssen sicherstellen, dass die ECU-Extraktion (<code>Extract ECU-Specific Information</code>) nicht direkt auf den unvollständigen Vorab-Eingängen operiert, sondern strikt auf einer validen <code>System Configuration Description</code> aufsetzt. Die Trennung zwischen System-Ebene und ECU-Ebene ist methodisch bindend: Erst der ECU-Extrakt ermöglicht das nachgelagerte ECU-Design und die BSW-/RTE-Konfiguration.</p>"}, {"id": "FIG-b83a579a824061af", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (Prozessflussdiagramm der AUTOSAR Methodology). Das Diagramm stellt den Übergang von der Systemkonfiguration zur ECU-spezifischen Konfigurationsebene innerhalb der AUTOSAR Classic Platform dar. Es fokussiert auf die Aktivitätskette unmittelbar nach Erstellung und Aktualisierung der Systemkonfigurationsbeschreibung und bildet die Brücke zur Teilmethodik „ECU Design and Configuration Methodology“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst Aktivitäten (gelbe Blockpfeile), Artefakte/Work Products (blaue XML-Dokumentensymbole bzw. weiße Dokumentenreferenz) sowie Toolunterstützung (gelbe Zeichendreieck-/Lineal-Symbole):</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsartefakte</strong>:</li>\n<li><code>System Configuration Input :System</code> (.XML)</li>\n<li><code>Collection of Available SWC Implementations</code> (.XML)</li>\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Configure System</code>: Nimmt die Eingangsbeschreibungen entgegen und erzeugt bzw. aktualisiert die Systemkonfiguration.</li>\n<li><code>Extract ECU-Specific Information</code>: Extrahiert die für ein einzelnes Steuergerät relevanten Daten aus der Systemkonfiguration.</li>\n<li><strong>Zwischen- und Ausgangsartefakte</strong>:</li>\n<li><code>System Configuration Description : System</code> (.XML): Zentrale Systemkonfigurationsbeschreibung, die aus <code>Configure System</code> resultiert und als Eingabe für <code>Extract ECU-Specific Information</code> sowie für die zyklische Rückführung dient.</li>\n<li>Weiteres <code>System Configuration Description</code>-Fragment / rückgeführtes Systemmodell (.XML) am unteren Rand.</li>\n<li><code>Continued in \"ECU Design and Configuration Methodology\"</code>: Weiterführungshinweis auf das ECU-spezifische Folge-Artefakt (ECU Extract of System Configuration).</li>\n<li><strong>Werkzeuge</strong>:</li>\n<li>AUTOSAR-Systemkonfigurationswerkzeug (assoziiert mit <code>Configure System</code>).</li>\n<li>AUTOSAR-ECU-Extraktionswerkzeug (assoziiert mit <code>Extract ECU-Specific Information</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Eingangsartefakte <code>System Configuration Input :System</code> und <code>Collection of Available SWC Implementations</code> fließen über gerichtete Kanten in den Prozessschritt <code>Configure System</code> ein.</li>\n<li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.</li>\n<li>Aus der <code>System Configuration Description : System</code> führt ein gerichteter Kontroll-/Datenfluss direkt in die nachgelagerte Aktivität <code>Extract ECU-Specific Information</code>.</li>\n<li>Parallel dazu existiert eine Rückkopplungs- bzw. Verfeinerungsschleife: Ein Pfeil führt von <code>Configure System</code> sowie eine gestrichelte Assoziation von <code>System Configuration Description : System</code> auf das darunterliegende XML-Artefakt der Systemkonfiguration.</li>\n<li><code>Extract ECU-Specific Information</code> verarbeitet die Systemkonfiguration und leitet das Ergebnis in den nachfolgenden Methodenbereich über, visualisiert durch das Referenzdokument <code>Continued in \"ECU Design and Configuration Methodology\"</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Prozessabfolge der AUTOSAR-Methodik. Entwickler und Tool-Hersteller müssen sicherstellen, dass die ECU-Extraktion (<code>Extract ECU-Specific Information</code>) nicht direkt auf den unvollständigen Vorab-Eingängen operiert, sondern strikt auf einer validen <code>System Configuration Description</code> aufsetzt. Die Trennung zwischen System-Ebene und ECU-Ebene ist methodisch bindend: Erst der ECU-Extrakt ermöglicht das nachgelagerte ECU-Design und die BSW-/RTE-Konfiguration.</p>"}], "trans": [{"from": "FIG-b2e2f38f4e92b10c", "to": "FIG-b83a579a824061af", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b83a579a824061af", "to": "FIG-b2e2f38f4e92b10c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
